negative_files.acceptance.yaml:
rule_files:
- rules.yaml
evaluation_interval: 1m
tests:
- name: queue-business-regression
  interval: 1m
  input_series:
  - series: queue_depth{queue="busy",env="prod",job="api"}
    values: 0 120 140 160 180 0 0 0
  - series: queue_workers{queue="busy",env="prod",job="api"}
    values: 1+0x7
  - series: queue_depth{queue="spike",env="prod",job="api"}
    values: 0 120 0 0 0 0 0 0
  - series: queue_workers{queue="spike",env="prod",job="api"}
    values: 1+0x7
  - series: queue_depth{queue="boundary",env="prod",job="api"}
    values: 100+0x7
  - series: queue_workers{queue="boundary",env="prod",job="api"}
    values: 1+0x7
  - series: queue_depth{queue="stopped",env="prod",job="api"}
    values: 50+0x7
  - series: queue_workers{queue="stopped",env="prod",job="api"}
    values: 0+0x7
  - series: queue_depth{queue="idle",env="prod",job="api"}
    values: 0+0x7
  - series: queue_workers{queue="idle",env="prod",job="api"}
    values: 0+0x7
  - series: queue_depth{queue="missing",env="prod",job="api"}
    values: 50+0x7
  - series: queue_depth{queue="cross",env="prod",job="bad"}
    values: 180+0x7
  - series: queue_workers{queue="cross",env="prod",job="bad"}
    values: 0+0x7
  - series: queue_depth{queue="cross",env="prod",job="good"}
    values: 0+0x7
  - series: queue_workers{queue="cross",env="prod",job="good"}
    values: 1+0x7
  - series: queue_depth{queue="dev-only",env="dev",job="api"}
    values: 200+0x7
  - series: queue_workers{queue="dev-only",env="dev",job="api"}
    values: 1+0x7
  alert_rule_test:
  - eval_time: 0m
    alertname: QueueBacklog
    exp_alerts: []
  - eval_time: 0m
    alertname: QueueWorkersUnavailable
    exp_alerts: []
  - eval_time: 0m
    alertname: QueueTelemetryMissing
    exp_alerts: []
  promql_expr_test: []
